#!/usr/bin/env python3
"""
topup_block10_to_580_words.py
Expands each part in Days 46 to 50 so that `say` has >= 585 words per part.
Rigorously focused on hardware coprocessors, Helium vector DSP, memory tiers, and sub-milliwatt silicon.
"""
import json

def get_word_count(part):
    return sum(len(s.split()) for s in part['say'])

def ensure_part_words(day_dict, part_idx, paragraphs, min_target=585):
    part = day_dict['parts'][part_idx]
    wc = get_word_count(part)
    for p in paragraphs:
        if wc >= min_target:
            break
        part['say'].append(p)
        wc = get_word_count(part)
    return wc

print("Loading Days 46-50 JSON files...")
days = {}
for d in range(46, 51):
    with open(f"scripts/iot_edge_day{d}.json", "r", encoding="utf-8") as f:
        days[d] = json.load(f)

